import{_ as a,a0 as p,w as L,s,ao as i,I as l,x as e,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"LKRG：用于运行时完整性检查的可加载内核模块 | LCTT x X-CMD","titleTemplate":false,"description":"LKRG：用于运行时完整性检查的可加载内核模块 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LKRG：用于运行时完整性检查的可加载内核模块 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LKRG：用于运行时完整性检查的可加载内核模块 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180204 LKRG- Linux to Get a Loadable Kernel Module for Runtime Integrity Checking","title":"LKRG：用于运行时完整性检查的可加载内核模块","tag":"201803","desc":""},"relativePath":"201803/20180204 LKRG- Linux to Get a Loadable Kernel Module for Runtime Integrity Checking.md","filePath":"[post].md"}'),u={name:"201803/20180204 LKRG- Linux to Get a Loadable Kernel Module for Runtime Integrity Checking.md"};function d(K,t,R,G,g,m){const n=p("Link");return L(),s("div",null,[t[20]||(t[20]=i('<h1 id="lkrg-用于运行时完整性检查的可加载内核模块" tabindex="-1">LKRG：用于运行时完整性检查的可加载内核模块 <a class="header-anchor" href="#lkrg-用于运行时完整性检查的可加载内核模块" aria-label="Permalink to “LKRG：用于运行时完整性检查的可加载内核模块”">​</a></h1><p><img src="https://www.bleepstatic.com/content/posts/2018/02/04/LKRG-logo.png" alt="LKRG logo"></p><p>开源社区的人们正在致力于一个 Linux 内核的新项目，它可以让内核更安全。命名为 Linux 内核运行时防护（Linux Kernel Runtime Guard，简称：LKRG），它是一个在 Linux 内核执行运行时完整性检查的可加载内核模块（LKM）。</p><p>它的用途是检测对 Linux 内核的已知的或未知的安全漏洞利用企图，以及去阻止这种攻击企图。</p><p>LKRG 也可以检测正在运行的进程的提权行为，在漏洞利用代码运行之前杀掉这个运行进程。</p><h3 id="这个项目开发始于-2011-年-首个版本已经发布" tabindex="-1">这个项目开发始于 2011 年，首个版本已经发布 <a class="header-anchor" href="#这个项目开发始于-2011-年-首个版本已经发布" aria-label="Permalink to “这个项目开发始于 2011 年，首个版本已经发布”">​</a></h3><p>因为这个项目开发的较早，LKRG 的当前版本仅仅是通过内核消息去报告违反内核完整性的行为，但是随着这个项目的成熟，将会部署一个完整的漏洞利用缓减系统。</p><p>LKRG 的成员 Alexander Peslyak 解释说，这个项目从 2011 年启动，并且 LKRG 已经经历了一个“重新开发&quot;阶段。</p>',8)),l("p",null,[t[3]||(t[3]=e("LKRG 的首个公开版本是 LKRG v0.0，它现在可以从 ",-1)),r(n,{href:"http://www.openwall.com/lkrg/"},{default:o(()=>[...t[0]||(t[0]=[e("这个页面",-1)])]),_:1}),t[4]||(t[4]=e(" 下载使用。",-1)),r(n,{href:"http://openwall.info/wiki/p_lkrg/Main"},{default:o(()=>[...t[1]||(t[1]=[e("这里",-1)])]),_:1}),t[5]||(t[5]=e(" 是这个项目的维基，为支持这个项目，它也有一个 ",-1)),r(n,{href:"https://www.patreon.com/p_lkrg"},{default:o(()=>[...t[2]||(t[2]=[e("Patreon 页面",-1)])]),_:1}),t[6]||(t[6]=e("。",-1))]),t[21]||(t[21]=i('<p>虽然 LKRG 仍然是一个开源项目，LKRG 的维护者也计划做一个 LKRG Pro 版本，这个版本将包含一个专用的 LKRG 发行版，它将支持对特定漏洞利用的检测，比如，容器泄漏。开发团队计划从 LKRG Pro 基金中提取部分资金用于保证项目的剩余工作。</p><h3 id="lkrg-是一个内核模块而不是一个补丁。" tabindex="-1">LKRG 是一个内核模块而不是一个补丁。 <a class="header-anchor" href="#lkrg-是一个内核模块而不是一个补丁。" aria-label="Permalink to “LKRG 是一个内核模块而不是一个补丁。”">​</a></h3><p>一个类似的项目是<ruby>附加内核监视器<rt>Additional Kernel Observer</rt></ruby>（AKO），但是 LKRG 与 AKO 是不一样的，因为 LKRG 是一个内核加载模块而不是一个补丁。LKRG 开发团队决定将它设计为一个内核模块是因为，在内核上打补丁对安全性、系统稳定性以及性能都有很直接的影响。</p><p>而以内核模块的方式提供，可以在每个系统上更容易部署 LKRG，而不必去修改核心的内核代码，修改核心的内核代码非常复杂并且很容易出错。</p><p>LKRG 内核模块在目前主流的 Linux 发行版上都可以使用，比如，RHEL7、OpenVZ 7、Virtuozzo 7、以及 Ubuntu 16.04 到最新的主线版本。</p><h3 id="它并非是一个完美的解决方案" tabindex="-1">它并非是一个完美的解决方案 <a class="header-anchor" href="#它并非是一个完美的解决方案" aria-label="Permalink to “它并非是一个完美的解决方案”">​</a></h3><p>LKRG 的创建者警告用户，他们并不认为 LKRG 是一个完美的解决方案，它<strong>提供不了</strong>坚不可摧和 100% 的安全。他们说，LKRG 是 “设计为<strong>可旁通</strong>的”，并且仅仅提供了“多元化安全” 的<strong>一个</strong>方面。</p><blockquote><p>虽然 LKRG 可以防御许多已有的 Linux 内核漏洞利用，而且也有可能会防御将来许多的（包括未知的）未特意设计去绕过 LKRG 的安全漏洞利用。它是设计为可旁通的（尽管有时候是以更复杂和/或低可利用为代价的）。因此，他们说 LKRG 通过多元化提供安全，就像运行一个不常见的操作系统内核一样，也就不会有真实运行一个不常见的操作系统的可用性弊端。</p></blockquote><p>LKRG 有点像基于 Windows 的防病毒软件，它也是工作于内核级别去检测漏洞利用和恶意软件。但是，LKRG 团队说，他们的产品比防病毒软件以及其它终端安全软件更加安全，因为它的基础代码量比较小，所以在内核级别引入新 bug 和漏洞的可能性就更小。</p><h3 id="运行当前版本的-lkrg-大约会带来-6-5-的性能损失" tabindex="-1">运行当前版本的 LKRG 大约会带来 6.5% 的性能损失 <a class="header-anchor" href="#运行当前版本的-lkrg-大约会带来-6-5-的性能损失" aria-label="Permalink to “运行当前版本的 LKRG 大约会带来 6.5% 的性能损失”">​</a></h3><p>Peslyak 说 LKRG 是非常适用于 Linux 机器的，它在修补内核的安全漏洞后不需要重启动机器。LKRG 允许用户持续运行带有安全措施的机器，直到在一个计划的维护窗口中测试和部署关键的安全补丁为止。</p><p>经测试显示，安装 LKRG v0.0 后大约会产生 6.5% 性能影响，但是，Peslyak 说将在后续的开发中持续降低这种影响。</p><p>测试也显示，LKRG 检测到了 CVE-2014-9322 (BadIRET)、CVE-2017-5123 (waitid(2) missing access_ok)、以及 CVE-2017-6074 (use-after-free in DCCP protocol) 的漏洞利用企图，但是没有检测到 CVE-2016-5195 (Dirty COW) 的漏洞利用企图。开发团队说，由于前面提到的“可旁通”的设计策略，LKRG 没有检测到 Dirty COW 提权攻击。</p><blockquote><p>在 Dirty COW 的测试案例中，由于 bug 机制的原因，使得 LKRG 发生了 “旁通”，并且这也是一种利用方法，它也是将来类似的以用户空间为目标的绕过 LKRG 的一种方法。这样的漏洞利用是否会是普通情况（不太可能！除非 LKRG 或者类似机制的软件流行起来），以及对它的可用性的（负面的）影响是什么？（对于那些直接目标是用户空间的内核漏洞来说，这不太重要，也并不简单）。</p></blockquote><hr>',15)),l("p",null,[t[8]||(t[8]=e("via: ",-1)),r(n,{href:"https://www.bleepingcomputer.com/news/linux/lkrg-linux-to-get-a-loadable-kernel-module-for-runtime-integrity-checking/"},{default:o(()=>[...t[7]||(t[7]=[e("https://www.bleepingcomputer.com/news/linux/lkrg-linux-to-get-a-loadable-kernel-module-for-runtime-integrity-checking/",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=e("作者：",-1)),r(n,{href:"https://www.bleepingcomputer.com/author/catalin-cimpanu/"},{default:o(()=>[...t[9]||(t[9]=[e("Catalin Cimpanu",-1)])]),_:1}),t[13]||(t[13]=e(" 译者：",-1)),r(n,{href:"https://github.com/qhwdw"},{default:o(()=>[...t[10]||(t[10]=[e("qhwdw",-1)])]),_:1}),t[14]||(t[14]=e(" 校对：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[17]||(t[17]=e("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原创编译，",-1)),r(n,{href:"https://linux.cn/"},{default:o(()=>[...t[16]||(t[16]=[e("Linux中国",-1)])]),_:1}),t[19]||(t[19]=e(" 荣誉推出",-1))])])}const b=a(u,[["render",d]]);export{x as __pageData,b as default};
